-- Client table MercenaryFlavourText: all 234 rows of the 3.29.3c client. Written by scripts/dev/client-sql.ps1.
INSERT INTO "MercenaryFlavourText" ("_row", "Id", "Description", "HASH16", "Tags", "TagWeight") VALUES
(0, 'NonEleBowRanger1', '"Even a lawless land needs rules. Even anarchy requires order." ' || char(13) || '
- Kylian Cyaxan', 22819, '[1195,1256]', '[0,1000]'),
(1, 'NonEleBowRanger2', 'As Cyaxan''s criminal empire grew, so too did its need for enforcers. The Trarthan militia was its answer. ', 25135, '[1195,1256]', '[0,1000]'),
(2, 'NonEleBowRanger3', 'Order came later. At first, the Trarthan militia was little more than muscle - sold to the highest house, and drunk on its coin.', 46485, '[1195,1256]', '[0,1000]'),
(3, 'NonEleBowRanger4', 'The Trarthan militia delivers justice swiftly - usually before a crime is even committed.', 50075, '[1195,1256]', '[0,1000]'),
(4, 'NonEleBowRanger5', '"The militia don''t keep the peace. They keep Trarthus profitable." ', 1655, '[1195,1256]', '[0,1000]'),
(5, 'NonEleBowRanger6', '"They weren''t just enforcers. They were reminders - of who ruled Korathin''s gutters, and what disobedience cost." ', 62209, '[1195,1256]', '[0,1000]'),
(6, 'NonEleBowRanger7', 'For a time, the militia had the slums on lockdown. Then Cyaxan flooded them with gems - and the streets ran red with blood. ', 49281, '[1195,1256]', '[0,1000]'),
(7, 'NonEleBowRanger8', 'Of all Kylian Cyaxan''s sins, virtue gems were the most costly. Blinded by greed, he never foresaw the chaos they''d unleash.', 20691, '[1195,1256]', '[0,1000]'),
(8, 'NonEleBowRanger9', 'Kylian Cyaxan demanded a swift response to the chaos in the streets. The militia answered - virtue gems in hand.', 18023, '[1195,1256]', '[0,1000]'),
(9, 'NonEleBowRanger10', 'The militia met fire with fire - gems for gems, blood for blood.', 37252, '[1195,1256]', '[0,1000]'),
(10, 'NonEleBowRanger11', 'With gems came power - and with power came fewer survivors of the militia''s ''justice''.', 60423, '[1195,1256]', '[0,1000]'),
(11, 'NonEleBowRanger12', '"They called it peace when the killing slowed. Not justice - just fewer people left to fight back... and even fewer who would dare." ', 8705, '[1195,1256]', '[0,1000]'),
(12, 'NonEleBowRangerNoble1', '{0} Cyaxan once kept order in Korathin''s worst quarter. Now she keeps trophies instead.', 38775, '[1258,1260]', '[1000,1000]'),
(13, 'NonEleBowRangerNoble2', '{0} was born of Cyaxan stock, raised on slum smoke and discipline.', 24942, '[1258,1260]', '[1000,1000]'),
(14, 'NonEleBowRangerNoble3', '{0} Cyaxan: a name once feared across the Trarthan militia ranks - feared even more now she''s off the leash.', 38714, '[1258,1260]', '[1000,1000]'),
(15, 'NonEleBowRangerNoble4', 'Trarthus was barren after the Vaal Cataclysm... until the Empire began exiling their unwanted to its bleak shores.', 9808, '[1258,1260]', '[1000,1000]'),
(16, 'NonEleBowRangerNoble5', '"Our ancestors were exiled so that the Eternal Empire could have its thousand-year peace. I don''t give a damn about Wraeclast."', 3719, '[1258,1260]', '[1000,1000]'),
(17, 'EleBowRanger1', 'Gems from Trarthus have their own trademarks. Like the populace, they are more brutal.', 53790, '[1195,1261]', '[0,1000]'),
(18, 'EleBowRanger2', 'Keitan slaves built the walls of Korathin. Kylian Cyaxan filled them with vice before the mortar had dried.', 19164, '[1195,1261]', '[0,1000]'),
(19, 'EleBowRanger3', 'Cyaxan brothels bore no name. But those who entered often forget their own. ', 23012, '[1195,1261]', '[0,1000]'),
(20, 'EleBowRanger4', 'First came desire. Then came dependency. Cyaxan offered both - by design.', 51626, '[1195,1261]', '[0,1000]'),
(21, 'EleBowRanger5', 'The courtesans were Cyaxan''s first pushers. Pleasure and powder ensured each customer returned - shaking a little more each time.  ', 5179, '[1195,1261]', '[0,1000]'),
(22, 'EleBowRanger6', 'Most were addicted before they even knew it - such was the potency of Cyaxan''s blend. ', 37109, '[1195,1261]', '[0,1000]'),
(23, 'EleBowRanger7', '"In the early days, the drug trade was shared. Then Cyaxan made sharing... unprofitable."', 63610, '[1195,1261]', '[0,1000]'),
(24, 'EleBowRanger8', 'When even dependency began to dull, Kylian Cyaxan sought something stronger - ''virtue'' in crystalline form.', 1475, '[1195,1261]', '[0,1000]'),
(25, 'EleBowRanger9', 'While most wielded gems for violence, Kylian Cyaxan saw in them something far more sordid.', 25908, '[1195,1261]', '[0,1000]'),
(26, 'EleBowRanger10', 'The first gem-lit flesh in Trarthus didn''t belong to a warrior. It belonged to a courtesan.', 28638, '[1195,1261]', '[0,1000]'),
(27, 'EleBowRanger12', 'Some gems enhanced sensation. Others suppressed it - turning bodies into tools of compliance.', 33846, '[1195,1261]', '[0,1000]'),
(28, 'EleBowRanger13', 'What began as pleasure became ritual. What began as choice became conditioning.', 56007, '[1195,1261]', '[0,1000]'),
(29, 'EleBowRanger14', '"Kylian Cyaxan is long dead - as are many of his customers. But the thing about that kind of customer? They replenish themselves."', 29242, '[1195,1261]', '[0,1000]'),
(30, 'EleBowRanger16', '"Brick and stone may hold a city... but pleasure holds a people."' || char(13) || '
 - Kylian Cyaxan', 24189, '[1195,1261]', '[0,1000]'),
(31, 'EleBowRangerNoble1', '{0} Cyaxan knew every back alley in Korathin - especially the ones that glittered.', 10473, '[1263,1265,1267]', '[1000,1000,1000]'),
(32, 'EleBowRangerNoble2', 'The gems are socketed deep. {0} Cyaxan''s need, deeper still.', 10665, '[1263,1265,1267]', '[1000,1000,1000]'),
(33, 'EleBowRangerNoble3', 'If it glints, {0} Cyaxan follows. If it runs, she chases.', 30228, '[1263,1265,1267]', '[1000,1000,1000]'),
(34, 'EleBowRangerNoble4', '"As decaying Empires are wont to do, the use of exile as a punishment gradually became more common over the centuries..."', 16, '[1263,1265,1267]', '[1000,1000,1000]'),
(35, 'EleBowRangerNoble5', 'The Eternal Empire eventually made their greatest mistake: they exiled a simple farmer to Trarthus.', 63215, '[1263,1265,1267]', '[1000,1000,1000]'),
(36, 'MeleeAOEMarauder1', 'In Korathin''s slave pits, Keita found its fortune. Death made for eager audiences.', 51315, '[1195,1224]', '[0,1000]'),
(37, 'MeleeAOEMarauder2', 'Keitan slaves raised the walls of Korathin. Their blood still clings to the mortar. ', 50223, '[1195,1224]', '[0,1000]'),
(38, 'MeleeAOEMarauder3', 'House Keita did not always command such fear. It was their crushing of the rebellion that made them a force to be reckoned with.  ', 37253, '[1195,1224]', '[0,1000]'),
(39, 'MeleeAOEMarauder4', 'The slave rebellion began with a whisper. A promise of freedom passed from throat to throat, louder each time.', 6010, '[1195,1224]', '[0,1000]'),
(40, 'MeleeAOEMarauder5', 'One night, the chains fell silent. The next, they snapped. Keitans awoke to fire in their camps and blood on their floors. ', 12292, '[1195,1224]', '[0,1000]'),
(41, 'MeleeAOEMarauder6', 'It took just three days. Three days for Keita to crush the dissidents, reforge the chains, and fill the pits with corpses.', 41155, '[1195,1224]', '[0,1000]'),
(42, 'MeleeAOEMarauder7', 'Keita left the rebels hanging, stripped and nameless. Not as martyrs - just meat, gone to waste.', 33085, '[1195,1224]', '[0,1000]'),
(43, 'MeleeAOEMarauder8', 'After the revolt, Ixan Keita declared the slaves must be reminded of their place. Thus began the Trarthan slave pits.', 45739, '[1195,1224]', '[0,1000]'),
(44, 'MeleeAOEMarauder9', 'From the ashes of rebellion came the slave pit - dug to remind the living what happened to those who sought freedom. ', 61285, '[1195,1224]', '[0,1000]'),
(45, 'MeleeAOEMarauder10', 'The slave pits are a reflection of Trarthan society: brutal, bloodthirsty, and swift to punish mistakes.  ', 24452, '[1195,1224]', '[0,1000]'),
(46, 'MeleeAOEMarauder11', 'Keita doesn''t fear uprisings anymore. Every lash, every cage, every pit - lessons carved in flesh.', 31091, '[1195,1224]', '[0,1000]'),
(47, 'MeleeAOEMarauder13', '"In Trarthus, freedom is earned, not given." ', 55803, '[1195,1224]', '[0,1000]'),
(48, 'MeleeAOEMarauderNoble1', '"The lucky ones die early. The rest learn to live with it."', 20797, '[1226,1228,1230]', '[1000,1000,1000]'),
(49, 'MeleeAOEMarauderNoble2', 'Fighting in chains taught {0} everything he needed - including how to break them. ', 22713, '[1226,1228,1230]', '[1000,1000,1000]'),
(50, 'MeleeAOEMarauderNoble3', 'Inside Trarthus or out, slave or slaver - none bred more enemies than House Keita. ', 3396, '[1226,1228,1230]', '[1000,1000,1000]'),
(51, 'MeleeAOEMarauderNoble4', 'The Trarthans paid back their debt to the Karui, aiding them when it was their turn to battle the Empire.', 43413, '[1226,1228,1230]', '[1000,1000,1000]'),
(52, 'MeleeAOEMarauderNoble5', 'When Tyndarus Phrecius tried to resupply his occupying legions on Trarthus, the Karui blockaded the Archipelago.', 62845, '[1226,1228,1230]', '[1000,1000,1000]'),
(53, 'MeleeStrikesMarauder1', 'Trarthan slavers are despicable - and indispensable.', 58696, '[1195,1231]', '[0,1000]'),
(54, 'MeleeStrikesMarauder2', 'Of all the Trarthan Death Trades, none strip the soul quite like slavery - brutal in both intent and execution.', 61712, '[1195,1231]', '[0,1000]'),
(55, 'MeleeStrikesMarauder15', 'Trarthus was built on the backs of slaves, whose labour shaped much of its infrastructure. At the whip-hand stood House Keita.', 17291, '[1195,1231]', '[0,1000]'),
(56, 'MeleeStrikesMarauder4', 'Cruel even by Trarthan standards, House Keita''s blend of brutality and efficiency made them ideal architects of the slave trade.', 32090, '[1195,1231]', '[0,1000]'),
(57, 'MeleeStrikesMarauder5', 'In their prime, Keita built more than cities - they built leverage. For a time, no House dared challenge their hold on Trarthus.', 3557, '[1195,1231]', '[0,1000]'),
(58, 'MeleeStrikesMarauder6', 'Ixan Keita helped build Trarthus - and nearly ruled it. But power begets ambition, and ambition always demands more.', 52255, '[1195,1231]', '[0,1000]'),
(59, 'MeleeStrikesMarauder7', 'The ambition of Ixan Keita was his undoing. His bid for power sparked war with Bardiya - a war Keita could not win.', 48362, '[1195,1231]', '[0,1000]'),
(60, 'MeleeStrikesMarauder8', 'Keita held the chains. Bardiya cut the purse strings. Trarthus watched as labour lost to leverage - and coin won the war.', 20364, '[1195,1231]', '[0,1000]'),
(61, 'MeleeStrikesMarauder9', 'Keita swore fealty to the Council with a clenched jaw. Better a seat at the table than exile from the game entirely.', 49165, '[1195,1231]', '[0,1000]'),
(62, 'MeleeStrikesMarauder10', 'Though the Keita of today is still a House of influence, Bardiya remembers their treachery - and limits their power accordingly. ', 32003, '[1195,1231]', '[0,1000]'),
(63, 'MeleeStrikesMarauder12', '"House Keita wrote the bloody book on cruelty. Think of the worst bastard you know - either they''re a Keitan, or a poor imitation."', 23825, '[1195,1231]', '[0,1000]'),
(64, 'MeleeStrikesMarauder13', ' "The Merchant Council''s a leash on House Keita - and the irony ain''t lost on ''em. Still, better leashed than buried."', 52710, '[1195,1231]', '[0,1000]'),
(65, 'MeleeStrikesMarauder14', '"Pain is the language of obedience."' || char(13) || '
 - Ixan Keita', 10120, '[1195,1231]', '[0,1000]'),
(66, 'MeleeStrikesMarauderNoble1', '{0} Keita built his name in the slave pits of Korathin - and built his fortune on the backs beneath him.', 14721, '[1233,1235]', '[1000,1000]'),
(67, 'MeleeStrikesMarauderNoble2', 'Slaves obeyed. Rivals bled. The rest learned to stay out of {0} Keita''s way.', 26180, '[1233,1235]', '[1000,1000]'),
(68, 'MeleeStrikesMarauderNoble3', 'The pits made killers of men... and monsters of those who ran them.', 47176, '[1233,1235]', '[1000,1000]'),
(69, 'MeleeStrikesMarauderNoble4', 'For centuries, ash from Karui volcanoes rode the wind to Trarthus. It turned slaves into the continent''s finest tools.', 58966, '[1233,1235]', '[1000,1000]'),
(70, 'MeleeStrikesMarauderNoble5', '"Slavery began in Trarthus when a simple farmer offered to serve and grow food in exchange for his life. Pathetic... but profitable."', 48413, '[1233,1235]', '[1000,1000]'),
(71, 'ElementalWitch1', 'Thaumaturgy in Trarthus is like smoke in the lungs - unpleasant, expected, and always present.', 64923, '[1195,1196]', '[0,1000]'),
(72, 'ElementalWitch2', ' Before vice, before gems, before brothels and powder - Cyaxan dealt in spices, cloth and coin. ', 28348, '[1195,1196]', '[0,1000]'),
(73, 'ElementalWitch3', ' "They all started legitimate - even Cyaxan. But virtue doesn''t buy power. Vice does."', 54937, '[1195,1196]', '[0,1000]'),
(74, 'ElementalWitch4', 'Cyaxan didn''t need blades. They had margins - and the power that comes from knowing what everyone else wanted.', 44282, '[1195,1196]', '[0,1000]'),
(75, 'ElementalWitch5', 'In time, margins thinned. Rivals grew bolder. So Cyaxan found new markets - darker ones.', 59324, '[1195,1196]', '[0,1000]'),
(76, 'ElementalWitch6', 'Cyaxan didn''t set out to rule the underworld. Only to survive it. Then survival turned to opportunity.', 55507, '[1195,1196]', '[0,1000]'),
(77, 'ElementalWitch7', 'Kylian Cyaxan''s ascent to lord of the Trarthan underworld was not without obstacles. The first arose within his own house. ', 46211, '[1195,1196]', '[0,1000]'),
(78, 'ElementalWitch8', 'Kylian''s first victim wasn''t a member of a rival House - it was family. From then on, betrayal became tradition.', 32573, '[1195,1196]', '[0,1000]'),
(79, 'ElementalWitch9', 'Kylian Cyaxan never raised his voice. Just his glass. The rest of the table never stood again.', 36337, '[1195,1196]', '[0,1000]'),
(80, 'ElementalWitch10', 'With rivals dead or disgraced, Kylian moved fast - consolidating power, ensuring no Cyaxan could rise as he had.', 26896, '[1195,1196]', '[0,1000]'),
(81, 'ElementalWitch11', 'Kylian never trusted alliances. He preferred leverage. Internally, that meant secrets. Externally, sabotage.', 24835, '[1195,1196]', '[0,1000]'),
(82, 'ElementalWitch13', '"When dining with a Cyaxan, bring an appetite - and an antidote." ', 15336, '[1195,1196]', '[0,1000]'),
(83, 'ElementalWitch14', 'Cyaxan rarely availed themselves of House Azadi''s services. They preferred less... bloody methods.', 8955, '[1195,1196]', '[0,1000]'),
(84, 'ElementalWitchNoble1', 'It wasn''t people {0} Cyaxan loathed, but the frailties they wore so proudly: need, artifice, expectation.', 44150, '[1198,1200,1202]', '[1000,1000,1000]'),
(85, 'ElementalWitchNoble2', 'Cold, restrained, detached - anathema to Cyaxan ideals. But death has many forms, and {0} excelled in hers.', 9347, '[1198,1200,1202]', '[1000,1000,1000]'),
(86, 'ElementalWitchNoble3', '{0} Cyaxan despised mess - of thought, of feeling, of flesh.', 51259, '[1198,1200,1202]', '[1000,1000,1000]'),
(87, 'ElementalWitchNoble4', '"Emperor Tyndarus Phrecius was a fool who let a wasteland full of exiles defy the Empire."', 24393, '[1198,1200,1202]', '[1000,1000,1000]'),
(88, 'ElementalWitchNoble5', '"Trarthus lives on, long after the dying husk of its parent Empire has become nothing but a memory."', 24784, '[1198,1200,1202]', '[1000,1000,1000]'),
(89, 'ChaosMinionWitch1', 'In the early days of Trarthus, each House kept to its corner. Peace held - not through trust, but through distance.', 44251, '[1195,1203]', '[0,1000]'),
(90, 'ChaosMinionWitch2', 'As each House drifted from legitimacy to vice, conflict was inevitable. Kylian Cyaxan made sure of it.', 39199, '[1195,1203]', '[0,1000]'),
(91, 'ChaosMinionWitch3', '"They say Kylian Cyaxan was once an upstanding merchant. But then, they say a lot of things."', 53525, '[1195,1203]', '[0,1000]'),
(92, 'ChaosMinionWitch4', '"To play both sides well is to leave no fingerprints - only consequences."' || char(13) || '
 - Kylian Cyaxan', 63099, '[1195,1203]', '[0,1000]'),
(93, 'ChaosMinionWitch5', 'History blames Bardiya and Keita for the Merchant Wars. Fewer recall that Cyaxan was whispering in both ears all along.', 59017, '[1195,1203]', '[0,1000]'),
(94, 'ChaosMinionWitch6', 'As Bardiya and Keita went to war, Kylian Cyaxan stayed neutral - by selling secrets to both sides.', 28393, '[1195,1203]', '[0,1000]'),
(95, 'ChaosMinionWitch7', '"A Cyaxan will stir the pot, watch it boil, then let others burn their hands - all while they slip out the back door."', 42821, '[1195,1203]', '[0,1000]'),
(96, 'ChaosMinionWitch8', '"There''s coin in war... so long as you''re not the one fighting it."' || char(13) || '
 - Kylian Cyaxan', 10524, '[1195,1203]', '[0,1000]'),
(97, 'ChaosMinionWitch9', 'The Merchant Wars began with tariffs and treaties. They ended with fire, famine, and grudges that would last a lifetime.', 22381, '[1195,1203]', '[0,1000]'),
(98, 'ChaosMinionWitch10', 'When all was said and done, the Merchant Wars had made fortunes for the few - and graves for the many.', 44667, '[1195,1203]', '[0,1000]'),
(99, 'ChaosMinionWitch11', 'Cyaxan may have lit the fire. But when bodies piled high and profits ran dry, even Kylian sought peace.', 65335, '[1195,1203]', '[0,1000]'),
(100, 'ChaosMinionWitch12', 'The end of the Merchant Wars came not from diplomacy, but depletion. The Houses didn''t shake hands - they paused to reload.', 35781, '[1195,1203]', '[0,1000]'),
(101, 'ChaosMinionWitch13', 'No House admits to starting the Merchant Wars. But every House claims to have won them.', 17900, '[1195,1203]', '[0,1000]'),
(102, 'ChaosMinionWitchNoble1', 'Some Cyaxans peddled pleasure, others poison. {0} Cyaxan peddled death.', 12104, '[1205,1207,1209]', '[1000,1000,1000]'),
(103, 'ChaosMinionWitchNoble2', 'Even {0}''s fellow Cyaxans questioned her methods. But never their efficacy.  ', 33843, '[1205,1207,1209]', '[1000,1000,1000]'),
(104, 'ChaosMinionWitchNoble3', 'Few in Trarthus kill with curses or corpses. But those who do face no fear of retribution.', 54892, '[1205,1207,1209]', '[1000,1000,1000]'),
(105, 'ChaosMinionWitchNoble4', '"They exiled their undesirables to Trarthus, and then had the gall to act surprised when those undesirables refused to bow down."', 61099, '[1205,1207,1209]', '[1000,1000,1000]'),
(106, 'ChaosMinionWitchNoble5', '"Witches aren''t feared in Trarthus. They''re adored. We wisely sided with the rebels against Little Tinny Phrecius."', 50775, '[1205,1207,1209]', '[1000,1000,1000]'),
(107, 'PhysConvertTemplar1', 'In Trarthus, faith never died. It just turned inward. ', 30741, '[1195,1249]', '[0,1000]'),
(108, 'PhysConvertTemplar2', 'The major Houses didn''t worship gods. They tried to become them. ', 5153, '[1195,1249]', '[0,1000]'),
(109, 'PhysConvertTemplar3', 'Divinity demands belief. Trarthus demanded proof. ', 40116, '[1195,1249]', '[0,1000]'),
(110, 'PhysConvertTemplar4', 'One claimed the mantle of flame. Another of blood. But in a city of rival ''gods'', none rose above the noise.', 2227, '[1195,1249]', '[0,1000]'),
(111, 'PhysConvertTemplar5', ' A House could rise through war, through gold, through secrets - but not through grace.', 65497, '[1195,1249]', '[0,1000]'),
(112, 'PhysConvertTemplar6', 'Ixan Keita declared himself a god - and built temples to prove it. His slaves were given no choice but to pray.', 8278, '[1195,1249]', '[0,1000]'),
(113, 'PhysConvertTemplar7', 'In his quest for Divinity, Ixan Keita demanded worship. Obedience was beaten in. But no man ever reached godhood through fear alone.', 50077, '[1195,1249]', '[0,1000]'),
(114, 'PhysConvertTemplar8', 'They sang of Ixan Keita, knelt in his hollow shrines... but their hearts spoke only of hate.', 21904, '[1195,1249]', '[0,1000]'),
(115, 'PhysConvertTemplar9', 'Ixan mistook silence for reverence. In truth, not one soul believed. And so he remained just that: a mortal soul.', 29229, '[1195,1249]', '[0,1000]'),
(116, 'PhysConvertTemplar10', '"Let them hate me, if they must. Even hatred bows to power."' || char(13) || '
 - Ixan Keita', 714, '[1195,1249]', '[0,1000]'),
(117, 'PhysConvertTemplar11', 'They preached in alleyways and taverns. Few listened. Fewer remembered.', 65002, '[1195,1249]', '[0,1000]'),
(118, 'PhysConvertTemplar12', 'Attempts to bring organised religion to Trarthus were many - and all of them met with blood.', 29232, '[1195,1249]', '[0,1000]'),
(119, 'PhysConvertTemplar13', 'Faith is tolerated in Trarthus - but only so long as it is kept to one''s self.', 1910, '[1195,1249]', '[0,1000]'),
(120, 'PhysConvertTemplar14', 'Even the pious stray in Trarthus - led not by devils, but by gold and supple skin.', 28108, '[1195,1249]', '[0,1000]'),
(121, 'PhysConvertTemplar15', 'Trarthans revere but one god: the almighty coin.', 43510, '[1195,1249]', '[0,1000]'),
(122, 'PhysConvertTemplar16', '"If your mission should take you to Trarthus, you''d best carry a knife."' || char(13) || '
 - Gospel and Blade', 13056, '[1195,1249]', '[0,1000]'),
(123, 'PhysConvertTemplarNoble1', '{0} Keita came to preach salvation. He left certain there was none to be found.', 22275, '[1251,1253,1255]', '[1000,1000,1000]'),
(124, 'PhysConvertTemplarNoble2', 'In a city built on secrets, faith never stood a chance.', 48664, '[1251,1253,1255]', '[1000,1000,1000]'),
(125, 'PhysConvertTemplarNoble3', 'Though born of Keita blood, {0} sought to better Trarthus through faith - until his kin reminded him where power truly lay.', 9549, '[1251,1253,1255]', '[1000,1000,1000]'),
(126, 'PhysConvertTemplarNoble4', 'Once Emperor Tyndarus caught wind of Trarthan warlords setting up a society, he sent his legions to stomp them back down.', 45384, '[1251,1253,1255]', '[1000,1000,1000]'),
(127, 'PhysConvertTemplarNoble5', 'The Phrecian legions executed the warlords of that era, and instituted crushing taxes on the budding Trarthan society.', 61014, '[1251,1253,1255]', '[1000,1000,1000]'),
(128, 'AurasMinionsTemplar1', 'Some foreigners cling to warm memories of Divinity. In Trarthus, that''s considered true madness.', 16075, '[1195,1241]', '[0,1000]'),
(129, 'AurasMinionsTemplar2', 'Trarthans know Innocence not as a god, but as a tale told by passing missionaries - and quickly forgotten.', 40666, '[1195,1241]', '[0,1000]'),
(130, 'AurasMinionsTemplar3', '"A fire that does not warm, does not feed, does not kill... what use is it in Trarthus?"', 41850, '[1195,1241]', '[0,1000]'),
(131, 'AurasMinionsTemplar4', 'Innocence preaches purity. Trarthus breeds survival. The two have little in common.', 64861, '[1195,1241]', '[0,1000]'),
(132, 'AurasMinionsTemplar5', '"When they call Korathin a city of sin, they''re not talking about the god."', 49559, '[1195,1241]', '[0,1000]'),
(133, 'AurasMinionsTemplar6', '"Some say there''s no honour left in Korathin. Others say it never belonged here to begin with." ', 7791, '[1195,1241]', '[0,1000]'),
(134, 'AurasMinionsTemplar7', 'A good deed in Trarthus gets you one thing: a target on your back. ', 34989, '[1195,1241]', '[0,1000]'),
(135, 'AurasMinionsTemplar8', '"What''s a man to do with morals, when no one else plays by them?" ', 27826, '[1195,1241]', '[0,1000]'),
(136, 'AurasMinionsTemplar10', 'Even in Trarthus, someone buries the bodies. Someone remembers the names. ', 18397, '[1195,1241]', '[0,1000]'),
(137, 'AurasMinionsTemplar11', 'Some virtues endure - not in law, nor gods, but in spite of both.', 31506, '[1195,1241]', '[0,1000]'),
(138, 'AurasMinionsTemplar12', 'The surest way to frighten Ixan Keita was kindness. Always hunting for an angle, he could never see it for what it was.', 64790, '[1195,1241]', '[0,1000]'),
(139, 'AurasMinionsTemplar13', 'Keita drew brutes from every corner - sadists, zealots, and worse. What bound them was a taste for cruelty.', 61092, '[1195,1241]', '[0,1000]'),
(140, 'AurasMinionsTemplarNoble1', 'They mocked {0} Keita''s prayers. Until one day, the sinner burned, and they said nothing more.', 47761, '[1248,1243,1247,1245]', '[0,1000,1000,1000]'),
(141, 'AurasMinionsTemplarNoble2', 'Trarthus could not unmake {0} Keita''s faith. But it tried. With ridicule. With pain. With temptation.', 56741, '[1248,1243,1247,1245]', '[0,1000,1000,1000]'),
(142, 'AurasMinionsTemplarNoble3', 'Innocence found no altar in Trarthus. Just one man.', 46324, '[1248,1243,1247,1245]', '[0,1000,1000,1000]'),
(143, 'AurasMinionsTemplarNoble4', 'In 870 IC, the four great Founders spurred their guerrilla rebellion into open warfare against the occupying legions.', 30194, '[1248,1243,1247,1245]', '[0,1000,1000,1000]'),
(144, 'AurasMinionsTemplarNoble5', 'It took two years of open warfare, but Tyndarus finally capitulated in exchange for the lives of his legions.', 29286, '[1248,1243,1247,1245]', '[0,1000,1000,1000]'),
(145, 'PhysicalDuelist1', 'Trarthus was lawless once - but not without rules. Some approached the Death Trades with grace... and surprising decorum.', 55333, '[1195,1268]', '[0,1000]'),
(146, 'PhysicalDuelist2', 'Before the Merchant Wars. Before the Council. Before Trarthus had a name. There was the Code.', 43354, '[1195,1268]', '[0,1000]'),
(147, 'PhysicalDuelist4', 'The Trarthan Code was not written - not at first. It was remembered. Passed in whispers, etched in scars.', 60669, '[1195,1268]', '[0,1000]'),
(148, 'PhysicalDuelist5', '"Break the Code, and you risked more than your life. You risked your name."', 53063, '[1195,1268]', '[0,1000]'),
(149, 'PhysicalDuelist6', 'Whether in gutters or along trade routes, the Code took root where laws could not.', 57497, '[1195,1268]', '[0,1000]'),
(150, 'PhysicalDuelist7', 'House Bardiya were first to back the Code - an early sign of their predilection for order and control.', 52636, '[1195,1268]', '[0,1000]'),
(151, 'PhysicalDuelist8', 'To House Azadi, the Code wasn''t a set of rules. It was a contract. And they never broke contracts.', 21670, '[1195,1268]', '[0,1000]'),
(152, 'PhysicalDuelist9', 'Cyaxan did not endorse the Code. Not at first. They waited, watched, and once it took hold, claimed they''d backed it all along.', 54646, '[1195,1268]', '[0,1000]'),
(153, 'PhysicalDuelist10', 'Even House Keita, for all their brutality, bowed to the Code. Not out of respect - but survival.', 54564, '[1195,1268]', '[0,1000]'),
(154, 'PhysicalDuelist11', 'Even under Council rule, the Code endures - now etched into law. ', 13811, '[1195,1268]', '[0,1000]'),
(155, 'PhysicalDuelist12', '"Travel to Trarthus is discouraged. Should you go, learn the Code - and honour it." - A Merchant''s Guide to Trarthus', 51983, '[1195,1268]', '[0,1000]'),
(156, 'PhysicalDuelist13', '"Break the Trarthan Code and you''ll likely be buried by someone who didn''t." - A Merchant''s Guide to Trarthus', 29581, '[1195,1268]', '[0,1000]'),
(157, 'PhysicalDuelist14', '"Those under the Great Houses shall answer any blood wager issued." ' || char(13) || '
- Trarthan Code, Article V', 38213, '[1195,1268]', '[0,1000]'),
(158, 'PhysicalDuelistNoble1', '{0} Azadi''s words? Withering. His blade? Equally so. ', 24075, '[1270,1272,1274]', '[1000,1000,1000]'),
(159, 'PhysicalDuelistNoble2', '"Elegance is not lost in violence - only in vulgarity."' || char(13) || '
 - {0} Azadi', 53100, '[1270,1272,1274]', '[1000,1000,1000]'),
(160, 'PhysicalDuelistNoble3', '"Ask any Azadin... You don''t get rich in Trarthus by being bad in a fight."' || char(13) || '
 - {0} Azadi', 28306, '[1270,1272,1274]', '[1000,1000,1000]'),
(161, 'PhysicalDuelistNoble4', '"The four Great Founders were not exiles. ''Twas the first Trarthan-born generation, once we actually had a modicum of society going."', 36872, '[1270,1272,1274]', '[1000,1000,1000]'),
(162, 'PhysicalDuelistNoble5', 'The four Great Houses were once begrudging allies, fighting a guerilla war against occupying legions.', 6776, '[1270,1272,1274]', '[1000,1000,1000]'),
(163, 'MeleeAOEStrikeDuelist1', 'Violence has always been common in Trarthus. But it was Ratha Azadi who commodified it - turned it into an art form all her own. ', 59635, '[1195,1275]', '[0,1000]'),
(164, 'MeleeAOEStrikeDuelist2', 'Azadi distinguished itself not through efficiency, but through audacious spectacle. Azadins didn''t kill. They wove death itself.', 7194, '[1195,1275]', '[0,1000]'),
(165, 'MeleeAOEStrikeDuelist3', 'Ratha Azadi understood that killing goes beyond the act itself. Some kills live longer than the killer - but only when done right.', 17773, '[1195,1275]', '[0,1000]'),
(166, 'MeleeAOEStrikeDuelist4', ' "Anywhere else, you''d kill from the shadows. But this is Trarthus - so we shout murder from the rooftops." - Ratha Azadi', 48219, '[1195,1275]', '[0,1000]'),
(167, 'MeleeAOEStrikeDuelist5', 'Would-be sadists flocked to House Azadi, seeking kin in their band of killers. But only a select few rose above the chaff.', 41156, '[1195,1275]', '[0,1000]'),
(168, 'MeleeAOEStrikeDuelist7', 'Among Azadi''s best, the mark mattered less than the method. To kill without flair was crude - commonplace. ', 52733, '[1195,1275]', '[0,1000]'),
(169, 'MeleeAOEStrikeDuelist8', 'A name etched in blood is still a name. Many Azadins died trying to earn theirs.', 28562, '[1195,1275]', '[0,1000]'),
(170, 'MeleeAOEStrikeDuelist9', 'Azadi''s finest were known for rivalry as much as skill. On one occasion, both died trying to outdo the other - while their mark fled.', 50895, '[1195,1275]', '[0,1000]'),
(171, 'MeleeAOEStrikeDuelist10', 'Audacious though they may be, Azadins don''t advertise. They let their work speak for itself.', 601, '[1195,1275]', '[0,1000]'),
(172, 'MeleeAOEStrikeDuelist11', 'Failure rang loudest of all. A botched kill meant the replacement made an example - of both target and Azadin.', 23512, '[1195,1275]', '[0,1000]'),
(173, 'MeleeAOEStrikeDuelist12', '"Anyone can kill. We give death a name, a face, a reputation."' || char(13) || '
 - Ratha Azadi ', 30623, '[1195,1275]', '[0,1000]'),
(174, 'MeleeAOEStrikeDuelist13', '"Those bloody Azadins...  Could kill twice the people in half the time if they weren''t so obsessed with ''artistry''." - Ixan Keita', 18706, '[1195,1275]', '[0,1000]'),
(175, 'MeleeAOEStrikeDuelistNoble1', '"Who needs paint, when blood spills so beautifully?"' || char(13) || '
 - {0} Azadi', 53658, '[1277,1279]', '[1000,1000]'),
(176, 'MeleeAOEStrikeDuelistNoble2', '{0} Azadi''s blade did more than silence. It left an impression. ', 22677, '[1277,1279]', '[1000,1000]'),
(177, 'MeleeAOEStrikeDuelistNoble3', '{0} Azadi: proof that his House''s legacy wasn''t written in history - but carved into flesh.', 15252, '[1277,1279]', '[1000,1000]'),
(178, 'MeleeAOEStrikeDuelistNoble4', 'Tyndarus tried to sail reinforcements west, but the Ezomytes burned his ships in the night, and supplied poisoned grain at port.', 32778, '[1277,1279]', '[1000,1000]'),
(179, 'MeleeAOEStrikeDuelistNoble5', '"Trarthus didn''t even ask the Ezomytes to aid them in the uprising. Those beautiful poetic bastards did it all on their own."', 39264, '[1277,1279]', '[1000,1000]'),
(180, 'DiverMercenary1', 'House Azadi''s reach extends even to the sea floor. There is nowhere they cannot find you.', 27076, '[1365]', '[1000]'),
(181, 'DiverMercenary2', 'Ratha would sooner string you up than send you to a watery grave. But sometimes, killers can''t be choosers.', 8999, '[1365]', '[1000]'),
(182, 'DiverMercenary3', 'Ratha''s wrath knew no bounds. Some ran from it. Others revelled in it. ', 56768, '[1365]', '[1000]'),
(183, 'TrapsMinesShadow1', 'The children of Korathin don''t play in fields. They play in slag.', 33606, '[1195,1210]', '[0,1000]'),
(184, 'TrapsMinesShadow2', 'The fields were quiet. The factories never were. One bred men. The other broke them.', 14549, '[1195,1210]', '[0,1000]'),
(185, 'TrapsMinesShadow3', 'A Trarthan farmer''s back bends with harvest. A cityman''s with hunger.', 9691, '[1195,1210]', '[0,1000]'),
(186, 'TrapsMinesShadow4', 'To the cityfolk, a broken tool is replaced. To the peasant, it''s a week lost.', 18553, '[1195,1210]', '[0,1000]'),
(187, 'TrapsMinesShadow5', 'The fields breed silence. The cities breed noise. Neither understands the other''s music.', 20613, '[1195,1210]', '[0,1000]'),
(188, 'TrapsMinesShadow6', '"Out in the country, a harvest is shared. Here in the city, it''s sold - then stolen back."', 19858, '[1195,1210]', '[0,1000]'),
(189, 'TrapsMinesShadow9', 'Korathin''s smog doesn''t just fill the sky. It seeps behind the eyes.', 12810, '[1195,1210]', '[0,1000]'),
(190, 'TrapsMinesShadow10', 'A thousand chimneys mark the skyline - monuments to what Trarthus built, and what it buried.', 37724, '[1195,1210]', '[0,1000]'),
(191, 'TrapsMinesShadow12', 'No songs are sung in Korathin factories. Just the rhythm of toil and breaking backs.', 45590, '[1195,1210]', '[0,1000]'),
(192, 'TrapsMinesShadowNoble1', 'Though rotten to the bone, Trarthus still shelters those the world cast aside.', 22700, '[1212,1214,1216]', '[1000,1000,1000]'),
(193, 'TrapsMinesShadowNoble2', 'A Mirror of Delirium cracked {0} Azadi''s mind like glass - or so the story goes.', 38745, '[1212,1214,1216]', '[1000,1000,1000]'),
(194, 'TrapsMinesShadowNoble3', 'To House Azadi, {0} is a relic. To everyone else, a warning.', 46712, '[1212,1214,1216]', '[1000,1000,1000]'),
(195, 'TrapsMinesShadowNoble4', '"The moment the four Great Founders actually won their war of independence, tensions began to rise between them."', 16190, '[1212,1214,1216]', '[1000,1000,1000]'),
(196, 'TrapsMinesShadowNoble5', '"The four great Founders were only allies out of necessity. It didn''t take much for their hard-won independence to fall apart."', 64460, '[1212,1214,1216]', '[1000,1000,1000]'),
(197, 'Crit1HShadow1', 'Azadi was last to rise among the major Houses. Where killing was common, no one paid for it  - until Azadi cornered the market.', 234, '[1195,1217]', '[0,1000]'),
(198, 'Crit1HShadow2', 'At first, anyone could kill for coin. House Azadi made the kill itself worth paying for. ', 39957, '[1195,1217]', '[0,1000]'),
(199, 'Crit1HShadow3', 'Independent killers didn''t last. Clients knew: hire Azadi, or become their next contract.', 60800, '[1195,1217]', '[0,1000]'),
(200, 'Crit1HShadow4', '"When palms need greasing, you go to House Bardiya. When heads need rolling, you send for House Azadi."', 11453, '[1195,1217]', '[0,1000]'),
(201, 'Crit1HShadow5', '"A masterful blend of audacity and discretion - that''s the Azadi trademark. You''ll know who made the kill, never who paid for it."', 58128, '[1195,1217]', '[0,1000]'),
(202, 'Crit1HShadow6', 'Azadi''s true currency wasn''t coin. It was reputation. And reputation, once wounded, bled.', 27988, '[1195,1217]', '[0,1000]'),
(203, 'Crit1HShadow7', 'Azadi contracts came sealed in wax. To break the seal was to accept the mark - and the consequences of failure.', 53081, '[1195,1217]', '[0,1000]'),
(204, 'Crit1HShadow8', 'Each Azadi contract was coded - names obscured, motives buried. But the message was always the same: kill. ', 57053, '[1195,1217]', '[0,1000]'),
(205, 'Crit1HShadow9', 'Some left trophies. Others left warnings. But all Azadins left a message: the job was done - and the debt had been paid. ', 24366, '[1195,1217]', '[0,1000]'),
(206, 'Crit1HShadow10', '"Everyone knows: renege on Azadi, and become their next target." ', 56269, '[1195,1217]', '[0,1000]'),
(207, 'Crit1HShadow11', '"To last in House Azadi, you need to be dead inside - or skilled at making others so. Preferably both."', 63960, '[1195,1217]', '[0,1000]'),
(208, 'Crit1HShadow13', '"In Trarthus, life is cheap. We made sure death wasn''t."' || char(13) || '
 - Ratha Azadi', 11698, '[1195,1217]', '[0,1000]'),
(209, 'Crit1HShadowNoble1', '{0} Azadi''s was not a style. It was a standard - silent, surgical, untraceable.', 26110, '[1219,1221,1223]', '[1000,1000,1000]'),
(210, 'Crit1HShadowNoble2', 'Where other Azadi painted death in crimson arcs, {0} delivered it with a whisper. ', 36545, '[1219,1221,1223]', '[1000,1000,1000]'),
(211, 'Crit1HShadowNoble3', 'In a House that prized spectacle, {0} Azadi offered none - only results. ', 61326, '[1219,1221,1223]', '[1000,1000,1000]'),
(212, 'Crit1HShadowNoble4', '"Trarthans never forget a debt. When the Ezomytes rebelled against the Empire, even though centuries had passed, we came to their aid."', 10766, '[1219,1221,1223]', '[1000,1000,1000]'),
(213, 'Crit1HShadowNoble5', '"Once our debts were paid to the Ezomytes and the Karui, we considered ourselves even. After that... well, might makes right."', 59652, '[1219,1221,1223]', '[1000,1000,1000]'),
(214, 'MiscScion1', 'The Merchant Council gave Trarthus a mask of order. Those who can''t wear it are cast out.', 8486, '[1195,1236]', '[0,1000]'),
(215, 'MiscScion2', 'Though they would not rule for years, the Bardiyans helped shape Trarthus - quiet power moving behind every deal and coin exchange.', 19147, '[1195,1236]', '[0,1000]'),
(216, 'MiscScion3', 'The first Bardiyan vault was carved into Korathin''s bedrock - long before the city rose above it.', 35356, '[1195,1236]', '[0,1000]'),
(217, 'MiscScion4', 'While the Keitans laid stone, the Bardiyans moved coin. One built a city in broad daylight. The other ran it from the shadows.', 27838, '[1195,1236]', '[0,1000]'),
(218, 'MiscScion5', 'Before the wars, there was trade. Keitan muscle, Bardiyan mind. Neither trusted the other - but both saw profit.', 21834, '[1195,1236]', '[0,1000]'),
(219, 'MiscScion6', 'No two Trarthan forefathers were more opposed - in ideology or in temperament - than Ixan Keita and Quilon Bardiya.  ', 44375, '[1195,1236]', '[0,1000]'),
(220, 'MiscScion7', 'Keita and Bardiya''s rivalry erupted across Trarthus - supply lines cut, coin vanished, and not a single soldier raised. ', 42488, '[1195,1236]', '[0,1000]'),
(221, 'MiscScion8', 'Keita demanded tribute. Bardiya and Azadi refused. The result: starvation, sabotage, and blood in the streets of Korathin. ', 45671, '[1195,1236]', '[0,1000]'),
(222, 'MiscScion9', 'Bardiya won their struggle with Keita. Coin proved more vital to Trarthus than all the slaves Keita could whip into labour.', 22019, '[1195,1236]', '[0,1000]'),
(223, 'MiscScion10', 'Bardiya''s victory over Keita came at a cost. From that pyrrhic win grew the Merchant Council - cooperative in name, Bardiyan in truth.', 54999, '[1195,1236]', '[0,1000]'),
(224, 'MiscScion11', 'House Bardiya remains as its forefather left it: clever, conniving, and always listening.', 46679, '[1195,1236]', '[0,1000]'),
(225, 'MiscScion12', '"A whisper in the right ear is stronger than any army."' || char(13) || '
 - Quilon Bardiya', 62363, '[1195,1236]', '[0,1000]'),
(226, 'MiscScion13', '"To rule through fear is to court your own demise. A frightened animal lashes out. A content one purrs in your lap." - Quilon Bardiya', 54193, '[1195,1236]', '[0,1000]'),
(227, 'MiscScion14', '"Bardiyans are clever, aye - but so ruthlessly self-serving it''s a wonder their banquets don''t end in blood."  ', 19699, '[1195,1236]', '[0,1000]'),
(228, 'MiscScionNoble1', '{0} was born into Bardiyan silk and silver - until a sibling whispered her inheritance away...', 28396, '[1238,1240]', '[1000,1000]'),
(229, 'MiscScionNoble2', '{0} Bardiya''s legacy was stolen. Her appetite remains. ', 40267, '[1238,1240]', '[1000,1000]'),
(230, 'MiscScionNoble3', 'Betrayal is currency in House Bardiya. {0} has never left a ledger unsettled. ', 17286, '[1238,1240]', '[1000,1000]'),
(231, 'MiscScionNoble4', 'The Eternal Empire stopped exiling people to Trarthus after 872 IC. They began building island prisons closer to home instead.', 21964, '[1238,1240]', '[1000,1000]'),
(232, 'MiscScionNoble5', '"The Empire essentially cut contact with Trarthus for five hundred years... until Chitus wanted our powder."', 51644, '[1238,1240]', '[1000,1000]'),
(233, 'AurasMinionsTemplarNobleNeon1', '''A ruckus that is made, may not be unmade.''' || char(13) || '
 - Trarthan Code Appendice XII', 11271, '[1248]', '[1000]');
